import {publicUrl} from '../../utils/const';

type imgProp = {
  linkImg: string;
}

export default function ImageProperty (linkImg: imgProp):JSX.Element {
  return(
    <div className="property__image-wrapper">
      <img className="property__image" src={`${publicUrl}/${linkImg.linkImg}`} alt="Studio" />
    </div>
  );
}
